"use client";

import {
  useMotionValueEvent,
  useReducedMotion,
  useScroll,
  useSpring,
  useTransform,
} from "motion/react";
import { useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { LAYERS, STOPS } from "./exploded-view/data";
import { ExplodedPhone } from "./exploded-view/exploded-phone";

// The nearest stop to a point of the story.
const nearestStop = (p: number) =>
  STOPS.reduce(
    (best, stop, index) =>
      Math.abs(stop.at - p) < Math.abs((STOPS[best]?.at ?? 0) - p)
        ? index
        : best,
    0,
  );

/**
 * A phone screen taken apart into its five layers as a person scrolls: it
 * tilts, spreads, labels each layer, gives each one focus, then closes. Tab
 * reaches the scrolling frame, where arrows, Page keys and Space move the
 * story, and seven stop buttons jump to each step. With reduced motion the
 * story moves in still frames, one per stop.
 */
export function ExplodedView({ className }: { className?: string }) {
  const titleId = useId();
  const captionId = useId();
  const reduceMotion = useReducedMotion() ?? false;
  const frameRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({ container: frameRef });
  const smooth = useSpring(scrollYProgress, {
    stiffness: 120,
    damping: 26,
    mass: 0.6,
  });
  const stepped = useTransform(
    scrollYProgress,
    (p) => STOPS[nearestStop(p)]?.at ?? 0,
  );
  const progress = reduceMotion ? stepped : smooth;
  const [stop, setStop] = useState(0);

  useMotionValueEvent(scrollYProgress, "change", (p) =>
    setStop(nearestStop(p)),
  );

  const jump = (index: number) => {
    const frame = frameRef.current;
    const target = STOPS[index];
    if (!frame || !target) return;
    frame.scrollTo({
      top: target.at * (frame.scrollHeight - frame.clientHeight),
      behavior: reduceMotion ? "auto" : "smooth",
    });
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="px-5 pt-5">
        <h2 id={titleId} className="text-base font-semibold">
          Inside the takings screen
        </h2>
        <p className="text-sm text-muted-foreground">
          Scroll the frame to take the screen apart, layer by layer.
        </p>
      </header>

      <div
        ref={frameRef}
        tabIndex={0}
        role="region"
        aria-label="Exploded view. Scroll to move through the story."
        aria-describedby={captionId}
        className="relative mx-5 mt-4 h-112 overflow-y-auto scroll-fade-effect-y scrollbar-none overscroll-contain rounded-xl bg-muted/40 outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        <div className="h-[300%]">
          <div className="sticky top-0 h-112 overflow-hidden">
            <ExplodedPhone progress={progress} />
          </div>
        </div>
      </div>

      <div className="flex flex-col gap-3 px-5 pt-3 pb-5">
        <p id={captionId} aria-live="polite" className="min-h-10 text-sm">
          <span className="font-medium">{STOPS[stop]?.title}.</span>{" "}
          {STOPS[stop]?.caption}
        </p>
        <div
          role="group"
          aria-label="Jump to a step"
          className="flex flex-wrap gap-1"
        >
          {STOPS.map((item, index) => (
            <Button
              key={item.title}
              variant={index === stop ? "secondary" : "ghost"}
              size="sm"
              aria-current={index === stop ? "step" : undefined}
              onClick={() => jump(index)}
            >
              {item.title}
            </Button>
          ))}
        </div>
        <ul className="sr-only">
          {LAYERS.map((layer) => (
            <li key={layer.id}>
              {layer.label}: {layer.about}
            </li>
          ))}
        </ul>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

/** One layer of the phone screen, bottom first. */
export interface ScreenLayer {
  id: string;
  label: string;
  /** What the layer holds, read out for a screen reader. */
  about: string;
}

/** The five layers, from the back of the screen to the front. */
export const LAYERS: ScreenLayer[] = [
  {
    id: "base",
    label: "Surface",
    about: "The background, the status bar and the clinic's name.",
  },
  {
    id: "total",
    label: "Weekly takings",
    about: "This week's takings, $4,820, with a switch between week and month.",
  },
  {
    id: "chart",
    label: "Day by day",
    about: "A bar chart of each day's takings, highest on Monday.",
  },
  {
    id: "rows",
    label: "Recent payments",
    about: "The last three card payments with the patient and the visit.",
  },
  {
    id: "toast",
    label: "Live notice",
    about: "A notice that a deposit just arrived.",
  },
];

/** A stop along the story: where the scroll sits, and the caption it shows. */
export interface StoryStop {
  at: number;
  title: string;
  caption: string;
}

/** The seven stops a person can jump to. */
export const STOPS: StoryStop[] = [
  {
    at: 0,
    title: "Screen",
    caption: "The takings screen a clinic owner opens each morning.",
  },
  {
    at: 0.2,
    title: "Tilt",
    caption: "The screen tips back so its depth shows.",
  },
  {
    at: 0.36,
    title: "Spread",
    caption: "Five layers pull apart, each with its own job.",
  },
  {
    at: 0.47,
    title: "Takings",
    caption:
      "The total sits above the surface, with its week and month switch.",
  },
  {
    at: 0.57,
    title: "Chart",
    caption: "The chart gives each day a bar, so a slow day stands out.",
  },
  {
    at: 0.67,
    title: "Payments",
    caption: "Recent payments and the live notice sit nearest the eye.",
  },
  {
    at: 1,
    title: "Together",
    caption: "The layers close and the screen stands up again.",
  },
];

/** This week's takings per day, Monday first, in pounds. */
export const WEEK = [920, 840, 610, 780, 700, 560, 410];

/** The latest payments on the screen. */
export const PAYMENTS = [
  { who: "M. Hale", what: "Physio follow-up", amount: 45 },
  { who: "R. Osei", what: "First consult", amount: 70 },
  { who: "J. Lund", what: "Sports massage", amount: 55 },
];

"use client";

import { motion, type MotionStyle, type MotionValue, useTransform } from "motion/react";

import { cn } from "@/lib/utils";

import { LAYERS } from "./data";
import { PhoneLayer } from "./phone-layer";
import { focusAt, labelAt, spreadAt, tiltAt } from "./story";

// Where each layer's label sits beside the phone, bottom layer first.
const LABEL_SPOT = ["bottom-6", "top-14", "top-36", "top-60", "bottom-2"];

/** One layer, lifted off the screen by the spread and dimmed when another layer has focus. */
function Layer({
  index,
  progress,
}: {
  index: number;
  progress: MotionValue<number>;
}) {
  const lift = useTransform(
    progress,
    (p) => `${spreadAt(p) * index * 5 + (focusAt(p) === index ? 1.2 : 0)}rem`,
  );
  const shade = useTransform(progress, (p) => {
    const focus = focusAt(p);
    return focus === null || focus === index || index === 0 ? 1 : 0.4;
  });
  const label = useTransform(progress, (p) => labelAt(p, index));
  const layer = LAYERS[index]!;
  // The motion values drive custom properties, and classes turn them into the transform and fade.
  return (
    <motion.div
      className="absolute inset-0 translate-z-(--lift) opacity-(--shade) transform-3d"
      // SAFETY: the object sets only CSS custom properties, which Motion animates from these motion values.
      style={{ "--lift": lift, "--shade": shade } as MotionStyle}
    >
      <PhoneLayer id={layer.id} />
      <motion.div
        className={cn(
          "pointer-events-none absolute left-full flex items-center opacity-(--label)",
          LABEL_SPOT[index],
        )}
        // SAFETY: the object sets only CSS custom properties, which Motion animates from these motion values.
        style={{ "--label": label } as MotionStyle}
      >
        <span className="block h-px w-10 origin-left scale-x-(--label) bg-muted-foreground @md:w-16" />
        <span className="ml-1 rounded-full border border-border bg-popover px-2 py-0.5 text-xs font-medium whitespace-nowrap text-popover-foreground shadow-sm">
          {layer.label}
        </span>
      </motion.div>
    </motion.div>
  );
}

/**
 * The phone screen as a stack of five layers in 3D. One progress value from
 * 0 to 1 drives it: the screen tilts back and turns, the layers spread,
 * labels draw in, each layer takes focus, then it all closes again.
 */
export function ExplodedPhone({ progress }: { progress: MotionValue<number> }) {
  const tiltX = useTransform(progress, (p) => `${tiltAt(p) * 52}deg`);
  const turn = useTransform(progress, (p) => `${tiltAt(p) * -32}deg`);
  const size = useTransform(progress, (p) => 1 - tiltAt(p) * 0.12);
  return (
    <div className="flex size-full items-center justify-center perspective-[75rem]">
      <motion.div
        className="relative h-96 w-48 -translate-x-8 scale-(--size) rotate-x-(--tilt) rotate-z-(--turn) transform-3d @md:translate-x-0"
        // SAFETY: the object sets only CSS custom properties, which Motion animates from these motion values.
        style={{ "--tilt": tiltX, "--turn": turn, "--size": size } as MotionStyle}
      >
        {LAYERS.map((layer, index) => (
          <Layer key={layer.id} index={index} progress={progress} />
        ))}
      </motion.div>
    </div>
  );
}

import type { CSSProperties } from "react";
import { cn } from "@/lib/utils";

import { formatMoney } from "../../lib/format";
import { CheckIcon } from "../../parts/icons";
import { PAYMENTS, WEEK } from "./data";

const PEAK = Math.max(...WEEK);
const DAY_LETTERS = ["M", "T", "W", "T", "F", "S", "S"];
const BARS = [
  "bg-chart-1",
  "bg-chart-2",
  "bg-chart-3",
  "bg-chart-4",
  "bg-chart-5",
  "bg-chart-1",
  "bg-chart-2",
];

/**
 * The drawing of one layer of the phone screen. Each layer fills the whole
 * screen, and only its own part is painted, so the stack reads as one
 * screen until it spreads apart. It is decoration: the layer list and the
 * caption carry the meaning.
 */
export function PhoneLayer({ id }: { id: string }) {
  if (id === "base") {
    return (
      <div className="size-full rounded-3xl border border-border bg-card shadow-xl">
        <div className="flex justify-between px-4 pt-2 text-xs text-muted-foreground">
          <span>09:41</span>
          <span>Harbour Street</span>
        </div>
      </div>
    );
  }
  if (id === "total") {
    return (
      <div className="absolute inset-x-3 top-8 flex flex-col gap-2">
        <div className="flex gap-1 self-start rounded-full bg-muted p-0.5 text-xs">
          <span className="rounded-full bg-background px-2 py-0.5 font-medium shadow-sm">
            Week
          </span>
          <span className="px-2 py-0.5 text-muted-foreground">Month</span>
        </div>
        <span className="text-xs text-muted-foreground">Takings this week</span>
        <span className="text-2xl font-semibold tracking-tight">
          {formatMoney(WEEK.reduce((sum, value) => sum + value, 0))}
        </span>
      </div>
    );
  }
  if (id === "chart") {
    return (
      <div className="absolute inset-x-3 top-32 flex h-20 items-end gap-1.5">
        {WEEK.map((value, index) => (
          <div
            key={index}
            className="flex h-full flex-1 flex-col items-center justify-end gap-1"
          >
            <span
              className={cn("h-(--bar) w-full rounded-t-md", BARS[index])}
              // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
              style={{ "--bar": `${(value / PEAK) * 80}%` } as CSSProperties}
            />
            <span className="text-xs text-muted-foreground">
              {DAY_LETTERS[index]}
            </span>
          </div>
        ))}
      </div>
    );
  }
  if (id === "rows") {
    return (
      <ul className="absolute inset-x-3 top-56 flex flex-col gap-1.5">
        {PAYMENTS.map((payment) => (
          <li
            key={payment.who}
            className="flex items-center justify-between rounded-lg bg-muted px-2 py-1.5 text-xs"
          >
            <span className="flex flex-col">
              <span className="font-medium">{payment.who}</span>
              <span className="text-muted-foreground">{payment.what}</span>
            </span>
            <span className="font-medium tabular-nums">
              {formatMoney(payment.amount)}
            </span>
          </li>
        ))}
      </ul>
    );
  }
  return (
    <div className="absolute inset-x-3 bottom-3 flex items-center gap-2 rounded-xl bg-foreground px-3 py-2 text-xs text-background shadow-lg">
      <CheckIcon aria-hidden="true" className="size-3.5" />
      Deposit of $30 received from A. Mistry
    </div>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
/** An arrow that points left, from the chosen icon pack. */
export const ArrowLeftIcon = packIcon("arrow-up", "-rotate-90");
/** An arrow that points up, from the chosen icon pack. */
export const ArrowUpIcon = packIcon("arrow-up");
/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

/** Rises from 0 to 1 as `value` moves from `from` to `to`, easing at both ends. */
export function rise(value: number, from: number, to: number): number {
  const t = Math.min(1, Math.max(0, (value - from) / (to - from)));
  return t * t * (3 - 2 * t);
}

/** How far the screen is tilted back, from 0 to 1. */
export const tiltAt = (p: number) => rise(p, 0.05, 0.22) - rise(p, 0.82, 0.96);

/** How far the layers are spread apart, from 0 to 1. */
export const spreadAt = (p: number) => rise(p, 0.18, 0.34) - rise(p, 0.76, 0.9);

/** How visible a layer's label is. Labels draw in from the bottom layer up. */
export const labelAt = (p: number, layer: number) =>
  rise(p, 0.3 + layer * 0.025, 0.36 + layer * 0.025) *
  (1 - rise(p, 0.74, 0.79));

/** Which layer has focus at this point of the story, or null when none does. */
export function focusAt(p: number): number | null {
  if (p < 0.41 || p >= 0.73) return null;
  if (p < 0.52) return 1;
  if (p < 0.62) return 2;
  return p < 0.68 ? 3 : 4;
}
